#include "postquantiquecoin/p2p/P2PMessage.h"
#include "postquantiquecoin/core/Serialization.h"
#include "postquantiquecoin/crypto/Hashing.h"
#include "postquantiquecoin/p2p/Protocol.h"
#include <algorithm>
namespace pqc::p2p { std::vector<uint8_t> P2PMessage::Serialize() const{ Serializer s; s.U32(magic); s.U32(networkId); s.String(command); s.Bytes(payload); auto h=pqc::Hashing::Sha3_256(payload); s.Bytes(std::vector<uint8_t>(h.begin(),h.begin()+8)); return s.Data(); } Result<P2PMessage> P2PMessage::Deserialize(const std::vector<uint8_t>& data,uint8_t expected){ Deserializer d(data); P2PMessage m; auto magic=d.U32(); if(magic.IsErr()) return Result<P2PMessage>::Err(magic.Error()); if(magic.Value()!=Magic) return Result<P2PMessage>::Err("bad p2p magic"); m.magic=magic.Value(); auto nid=d.U32(); if(nid.IsErr()) return Result<P2PMessage>::Err(nid.Error()); m.networkId=static_cast<uint8_t>(nid.Value()); if(expected&&m.networkId!=expected) return Result<P2PMessage>::Err("wrong network id"); auto cmd=d.String(); if(cmd.IsErr()) return Result<P2PMessage>::Err(cmd.Error()); m.command=cmd.Value(); if(std::find(KnownCommands().begin(),KnownCommands().end(),m.command)==KnownCommands().end()) return Result<P2PMessage>::Err("unknown command"); auto payload=d.Bytes(); if(payload.IsErr()) return Result<P2PMessage>::Err(payload.Error()); if(payload.Value().size()>MaxPayloadBytes) return Result<P2PMessage>::Err("oversized payload"); m.payload=payload.Value(); auto chk=d.Bytes(); if(chk.IsErr()) return Result<P2PMessage>::Err(chk.Error()); auto h=pqc::Hashing::Sha3_256(m.payload); if(chk.Value().size()!=8||!std::equal(chk.Value().begin(),chk.Value().end(),h.begin())) return Result<P2PMessage>::Err("message checksum mismatch"); return Result<P2PMessage>::Ok(m);} }
